alter table vzc.control_authority_decisions add constraint control_authority_decisions_decision_request_unique unique (decision_id, control_request_id);
alter table vzc.control_execution_receipts drop constraint control_execution_receipts_authority_decision_id_fkey;
alter table vzc.control_execution_receipts add constraint control_execution_receipts_decision_request_fkey foreign key (authority_decision_id, control_request_id) references vzc.control_authority_decisions(decision_id, control_request_id) on delete restrict;
create or replace function vzc.enforce_control_request_target() returns trigger language plpgsql security invoker set search_path='' as $$ begin if not exists (select 1 from vzc.device_bindings d where d.device_binding_id=new.target_device_binding_id and d.control_capable=true and d.trust_state in ('verified','trusted')) then raise exception 'VZC control target must be control-capable and verified/trusted'; end if; return new; end $$;
revoke all on function vzc.enforce_control_request_target() from public,anon,authenticated; grant execute on function vzc.enforce_control_request_target() to service_role;
create trigger vzc_control_request_target_guard before insert or update of target_device_binding_id on vzc.control_requests for each row execute function vzc.enforce_control_request_target();
create or replace function vzc.enforce_control_execution_authority() returns trigger language plpgsql security invoker set search_path='' as $$ declare d text; decision_at_ts timestamptz; req_exp timestamptz; begin select a.decision,a.decision_at,r.expires_at into d,decision_at_ts,req_exp from vzc.control_authority_decisions a join vzc.control_requests r on r.control_request_id=a.control_request_id where a.decision_id=new.authority_decision_id and a.control_request_id=new.control_request_id; if d is distinct from 'authorized' then raise exception 'VZC execution requires an authorized authority decision'; end if; if req_exp is not null and coalesce(new.executed_at,now()) >= req_exp then raise exception 'VZC execution authorization expired'; end if; if exists (select 1 from vzc.control_authority_decisions x where x.control_request_id=new.control_request_id and x.decision='revoked' and x.decision_at >= decision_at_ts and x.decision_at <= coalesce(new.executed_at,now())) then raise exception 'VZC execution authorization was revoked'; end if; return new; end $$;
revoke all on function vzc.enforce_control_execution_authority() from public,anon,authenticated; grant execute on function vzc.enforce_control_execution_authority() to service_role;
create trigger vzc_control_execution_authority_guard before insert or update of authority_decision_id,control_request_id,executed_at on vzc.control_execution_receipts for each row execute function vzc.enforce_control_execution_authority();
alter table vzc.technology_candidate_bindings add constraint technology_candidate_pilot_rights_gate check (candidate_state not in ('bounded_prototype','pilot_candidate','pilot_approved','pilot_evaluation','scale_or_commercial_decision') or (rights_status in ('verified_for_evaluation','licensed_or_authorized') and rights_reference is not null));
create or replace function vzc.enforce_pilot_deployment_gate() returns trigger language plpgsql security invoker set search_path='' as $$ declare s text; vf timestamptz; vu timestamptz; begin if new.pilot_state in ('pilot_approved','pilot_active','evaluation','closed','scale_recommended','scale_not_recommended') then select deployment_stage,valid_from,valid_until into s,vf,vu from vzc.deployment_authorization_gates where deployment_gate_id=new.deployment_gate_id; if s not in ('pilot_approved','pilot_active','production_approved') then raise exception 'VZC pilot requires pilot-approved or stronger deployment gate'; end if; if vf is not null and now()<vf then raise exception 'VZC deployment gate not yet valid'; end if; if vu is not null and now()>=vu then raise exception 'VZC deployment gate expired'; end if; end if; if new.pilot_state='pilot_active' and new.start_at is null then raise exception 'VZC active pilot requires explicit start_at'; end if; return new; end $$;
revoke all on function vzc.enforce_pilot_deployment_gate() from public,anon,authenticated; grant execute on function vzc.enforce_pilot_deployment_gate() to service_role;
create trigger vzc_pilot_deployment_gate_guard before insert or update of pilot_state,deployment_gate_id,start_at on vzc.pilot_registry for each row execute function vzc.enforce_pilot_deployment_gate();
create or replace view vzc.pilot_acceptance_read_model with (security_invoker=true) as select p.pilot_id,p.pilot_code,p.pilot_class,p.pilot_state,p.scope_reference,p.start_at,p.end_at,g.deployment_stage,g.valid_from as gate_valid_from,g.valid_until as gate_valid_until,count(distinct m.pilot_metric_definition_id) as metric_count,count(distinct o.pilot_metric_observation_id) as observation_count,count(distinct e.pilot_outcome_evaluation_id) as evaluation_count from vzc.pilot_registry p left join vzc.deployment_authorization_gates g on g.deployment_gate_id=p.deployment_gate_id left join vzc.pilot_metric_definitions m on m.pilot_id=p.pilot_id left join vzc.pilot_metric_observations o on o.pilot_metric_definition_id=m.pilot_metric_definition_id left join vzc.pilot_outcome_evaluations e on e.pilot_id=p.pilot_id group by p.pilot_id,p.pilot_code,p.pilot_class,p.pilot_state,p.scope_reference,p.start_at,p.end_at,g.deployment_stage,g.valid_from,g.valid_until;
revoke all on vzc.pilot_acceptance_read_model from public,anon,authenticated; grant select on vzc.pilot_acceptance_read_model to service_role;
create or replace view vzc.control_acceptance_read_model with (security_invoker=true) as select r.control_request_id,r.request_state,r.target_device_binding_id,d.device_key,d.trust_state,d.control_capable,r.requested_action,r.requested_at,r.expires_at,a.decision_id,a.decision,a.decision_at,x.execution_receipt_id,x.execution_state,x.executed_at from vzc.control_requests r join vzc.device_bindings d on d.device_binding_id=r.target_device_binding_id left join lateral (select z.* from vzc.control_authority_decisions z where z.control_request_id=r.control_request_id order by z.decision_at desc limit 1) a on true left join vzc.control_execution_receipts x on x.control_request_id=r.control_request_id and x.authority_decision_id=a.decision_id;
revoke all on vzc.control_acceptance_read_model from public,anon,authenticated; grant select on vzc.control_acceptance_read_model to service_role;
